// ============================================================
//  CONFIGURATION
// ============================================================
const CONFIG = {
  brand: 'Portefolia',
  tagline: 'Expose ton futur.',
  frontUrl: 'https://portefolia.tech',
  apiUrl: 'https://portefolia.tech/api',          // ou http://localhost:<port>/api si n8n tourne sur le même VPS
  fromEmail: 'Portefolia <support@portefolia.tech>', // doit être l'adresse du compte SMTP
  replyTo: 'support@portefolia.tech',
  adminEmail: 'diankaseydou52@gmail.com',             // reçoit toutes les notifications de la plateforme
  supportWhatsapp: '+221 78 131 13 71',
  colors: { primary: '#1B5E20', accent: '#2E7D32' },
};
return $input.all().map((i) => ({ json: { ...i.json, config: CONFIG } }));

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fcfa = (n) => String(Math.round(Number(n) || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + ' F CFA';
const para = (html) => `<p style="font-size:15px;line-height:1.6;margin:0 0 12px">${html}</p>`;
const table = (rows) => `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font-size:14px;border-top:1px solid #e5e7eb;border-bottom:1px solid #e5e7eb;margin:16px 0">${rows
  .filter((r) => r && r[1] !== undefined && r[1] !== null && r[1] !== '')
  .map(([k, v, raw]) => `<tr><td style="padding:7px 0;color:#6b7280;width:42%;vertical-align:top">${esc(k)}</td><td style="padding:7px 0;font-weight:600">${raw ? v : esc(v)}</td></tr>`).join('')}</table>`;
const dateFr = (d) => { if (!d) return ''; const x = new Date(d); return Number.isNaN(x.getTime()) ? String(d) : x.toLocaleDateString('fr-FR', { day: 'numeric', month: 'long', year: 'numeric' }); };

function layout(cfg, { preheader = '', title, body, cta, footer }) {
  const button = cta && cta.url
    ? `<p style="margin:28px 0 8px;text-align:center"><a href="${esc(cta.url)}" style="background:${cfg.colors.accent};color:#ffffff;text-decoration:none;padding:14px 26px;border-radius:8px;font-weight:600;display:inline-block">${esc(cta.label)}</a></p>`
    : '';
  return `<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title></head>
<body style="margin:0;background:#f4f5f7;font-family:Arial,Helvetica,sans-serif;color:#1f2937">
<span style="display:none;max-height:0;overflow:hidden;opacity:0">${esc(preheader)}</span>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f7;padding:24px 12px"><tr><td align="center">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:12px;overflow:hidden">
<tr><td style="background:${cfg.colors.primary};padding:22px 28px;color:#ffffff;font-size:20px;font-weight:700">${esc(cfg.brand)}<div style="font-size:12px;font-weight:400;opacity:.85;margin-top:4px">${esc(cfg.tagline)}</div></td></tr>
<tr><td style="padding:28px">
<h1 style="font-size:20px;line-height:1.3;margin:0 0 16px">${esc(title)}</h1>
${body}
${button}
</td></tr>
<tr><td style="padding:18px 28px;background:#f9fafb;font-size:12px;line-height:1.5;color:#6b7280">${footer || 'Notification automatique de la plateforme Portefolia.'}</td></tr>
</table></td></tr></table></body></html>`;
}

// ---------- Relances des comptes expirés (J+3, J+10, J+30, J+60) ----------
const cfg = $('Config (relances)').first().json.config;
const data = $input.first().json || {};
const out = [];

for (const r of (data.reminders || [])) {
  const u = r.user || {};
  if (!u.email) continue;
  const prenom = esc(u.first_name || '');
  const plan = (r.plan && r.plan.name) || 'Portefolia';
  const visits = Number((r.stats || {}).visits_30d) || 0;
  const hello = prenom ? `${prenom}, ` : '';
  const since = r.expired_on ? `le ${esc(dateFr(r.expired_on))}` : 'récemment';
  const lost = para('Votre portfolio reste en ligne, mais l\'accès à votre espace est suspendu : vous ne pouvez plus le modifier, ajouter vos nouveaux projets ni consulter vos statistiques.');
  const visitLine = visits > 0
    ? para(`Votre portfolio a encore reçu <strong>${visits}</strong> visite${visits > 1 ? 's' : ''} ces 30 derniers jours : vos visiteurs voient un profil qui n'évolue plus.`)
    : '';
  const kept = para('Tout votre contenu est conservé : projets, compétences, expériences. En renouvelant, vous reprenez exactement là où vous en étiez.');
  const howTo = para('Le renouvellement prend 2 minutes et se paie par Wave.');

  let subject;
  let title;
  let body;
  switch (r.step) {
    case 'J+3':
      subject = `${hello}votre abonnement Portefolia a expiré`;
      title = `Votre abonnement ${plan} a expiré`;
      body = para(`Votre abonnement <strong>${esc(plan)}</strong> a pris fin ${since}.`) + lost + visitLine + howTo;
      break;
    case 'J+10':
      subject = `${hello}votre portfolio n'est plus à jour depuis ${r.days_expired} jours`;
      title = 'Votre portfolio vous attend';
      body = para(`Cela fait ${esc(r.days_expired)} jours que votre abonnement ${esc(plan)} a expiré.`) + visitLine + lost + kept + howTo;
      break;
    case 'J+30':
      subject = `${hello}on garde votre portfolio au chaud`;
      title = 'Votre contenu est toujours là';
      body = para('Votre compte Portefolia est en pause depuis un mois.') + kept + visitLine + howTo;
      break;
    default:
      subject = `Dernier rappel : réactivez votre compte Portefolia`;
      title = `${prenom ? prenom + ', d' : 'D'}ernier rappel`;
      body = para(`Votre abonnement ${esc(plan)} a expiré ${since}. C'est notre dernier rappel : nous ne vous écrirons plus à ce sujet.`) + kept + howTo
        + para(`Une question ou un souci de paiement ? Écrivez-nous sur WhatsApp au ${esc(cfg.supportWhatsapp)}.`);
  }

  const footer = `Vous recevez cet e-mail car votre abonnement Portefolia a expiré. <a href="${esc((r.links || {}).unsubscribe_url)}" style="color:#6b7280">Ne plus recevoir ces rappels</a>.`;
  out.push({ json: {
    relance_id: r.relance_id,
    step: r.step,
    to: u.email,
    from: cfg.fromEmail,
    replyTo: cfg.replyTo,
    subject,
    html: layout(cfg, { preheader: subject, title, body, cta: { label: 'Réactiver mon compte', url: (r.links || {}).renew_url || cfg.frontUrl + '/renouveler' }, footer }),
  } });
}
return out;

// ============================================================
//  CONFIGURATION
// ============================================================
const CONFIG = {
  brand: 'Portefolia',
  tagline: 'Expose ton futur.',
  frontUrl: 'https://portefolia.tech',
  apiUrl: 'https://portefolia.tech/api',          // ou http://localhost:<port>/api si n8n tourne sur le même VPS
  fromEmail: 'Portefolia <support@portefolia.tech>', // doit être l'adresse du compte SMTP
  replyTo: 'support@portefolia.tech',
  adminEmail: 'diankaseydou52@gmail.com',             // reçoit toutes les notifications de la plateforme
  supportWhatsapp: '+221 78 131 13 71',
  colors: { primary: '#1B5E20', accent: '#2E7D32' },
};
return $input.all().map((i) => ({ json: { ...i.json, config: CONFIG } }));

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fcfa = (n) => String(Math.round(Number(n) || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + ' F CFA';
const para = (html) => `<p style="font-size:15px;line-height:1.6;margin:0 0 12px">${html}</p>`;
const table = (rows) => `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font-size:14px;border-top:1px solid #e5e7eb;border-bottom:1px solid #e5e7eb;margin:16px 0">${rows
  .filter((r) => r && r[1] !== undefined && r[1] !== null && r[1] !== '')
  .map(([k, v, raw]) => `<tr><td style="padding:7px 0;color:#6b7280;width:42%;vertical-align:top">${esc(k)}</td><td style="padding:7px 0;font-weight:600">${raw ? v : esc(v)}</td></tr>`).join('')}</table>`;
const dateFr = (d) => { if (!d) return ''; const x = new Date(d); return Number.isNaN(x.getTime()) ? String(d) : x.toLocaleDateString('fr-FR', { day: 'numeric', month: 'long', year: 'numeric' }); };

function layout(cfg, { preheader = '', title, body, cta, footer }) {
  const button = cta && cta.url
    ? `<p style="margin:28px 0 8px;text-align:center"><a href="${esc(cta.url)}" style="background:${cfg.colors.accent};color:#ffffff;text-decoration:none;padding:14px 26px;border-radius:8px;font-weight:600;display:inline-block">${esc(cta.label)}</a></p>`
    : '';
  return `<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title></head>
<body style="margin:0;background:#f4f5f7;font-family:Arial,Helvetica,sans-serif;color:#1f2937">
<span style="display:none;max-height:0;overflow:hidden;opacity:0">${esc(preheader)}</span>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f7;padding:24px 12px"><tr><td align="center">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:12px;overflow:hidden">
<tr><td style="background:${cfg.colors.primary};padding:22px 28px;color:#ffffff;font-size:20px;font-weight:700">${esc(cfg.brand)}<div style="font-size:12px;font-weight:400;opacity:.85;margin-top:4px">${esc(cfg.tagline)}</div></td></tr>
<tr><td style="padding:28px">
<h1 style="font-size:20px;line-height:1.3;margin:0 0 16px">${esc(title)}</h1>
${body}
${button}
</td></tr>
<tr><td style="padding:18px 28px;background:#f9fafb;font-size:12px;line-height:1.5;color:#6b7280">${footer || 'Notification automatique de la plateforme Portefolia.'}</td></tr>
</table></td></tr></table></body></html>`;
}

// ---------- Récapitulatif quotidien pour l'administrateur ----------
const cfg = $('Config (récap)').first().json.config;
const d = $input.first().json || {};
const U = d.users || {}; const R = d.revenue || {}; const S = d.subscriptions || {}; const N = d.nfc || {}; const L = d.links || {};
const FLUX = { ABONNEMENT: 'Abonnements', REABONNEMENT: 'Réabonnements', UPGRADE: 'Changements de formule', NFC: 'Cartes NFC', AUTRE: 'Autres' };

const todo = [];
if (S.pending_wave) todo.push(`${S.pending_wave} paiement(s) Wave d'abonnement à valider`);
if (N.to_validate) todo.push(`${N.to_validate} paiement(s) de carte NFC à valider`);
if (N.ready_to_print) todo.push(`${N.ready_to_print} carte(s) NFC prête(s) à imprimer`);
if (S.expiring_7d) todo.push(`${S.expiring_7d} abonnement(s) expirent dans les 7 jours`);

const body =
  table([
    ['Inscriptions du jour', `${U.today || 0} (total : ${U.total || 0})`],
    ['Encaissé aujourd\'hui', fcfa(R.today)],
    ['Encaissé ce mois-ci', fcfa(R.month)],
    ['Abonnements actifs', S.active || 0],
    ['Expirés aujourd\'hui', S.expired_today || 0],
    ['Relances envoyées', d.relances_sent_today || 0],
    ['Commandes de cartes NFC', N.orders_today || 0],
    ['Messages de contact', d.contacts_today || 0],
  ])
  + ((R.by_type || []).length ? para('<strong>Encaissements du jour</strong><br>' + R.by_type.map((t) => `${esc(FLUX[t.type] || t.type)} : ${esc(t.count)} · ${esc(fcfa(t.total))}`).join('<br>')) : '')
  + ((U.latest || []).length ? para('<strong>Nouveaux comptes</strong><br>' + U.latest.map((x) => `${esc(x.name || x.email)} — ${esc(x.email)}`).join('<br>')) : '')
  + (todo.length ? para('<strong>À traiter</strong><br>' + todo.map((t) => '• ' + esc(t)).join('<br>')) : para('Rien en attente de votre côté. 👍'));

const subject = `📊 Portefolia — ${dateFr(d.date)} : ${U.today || 0} inscription(s), ${fcfa(R.today)} encaissés`;
return [{ json: { to: cfg.adminEmail, from: cfg.fromEmail, replyTo: cfg.replyTo, subject,
  html: layout(cfg, { preheader: subject, title: `Récapitulatif du ${dateFr(d.date)}`, body, cta: { label: 'Ouvrir le tableau de bord', url: L.dashboard_url || cfg.frontUrl + '/admin/dashboard' } }) } }];
